if (isRemoveLP) {
feeAmount += tAmount.mul(_removeLPFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
} else if (isAddLP) {
feeAmount += tAmount.mul(_addLPFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
